import http from "node:http";
import { URL } from "node:url";
import pg from "pg";

const { Pool } = pg;

const PORT = Number(process.env.PORT ?? 3000);
const postgresUrl = process.env.POSTGRES_URL;
const clickhouseUrl = process.env.CLICKHOUSE_URL;

if (!postgresUrl) {
  console.error("POSTGRES_URL is required");
  process.exit(1);
}
if (!clickhouseUrl) {
  console.error("CLICKHOUSE_URL is required");
  process.exit(1);
}

const pgPool = new Pool({ connectionString: postgresUrl });

/** @type {Map<number, string> | null} */
let regionNames = null;
/** @type {Map<number, string> | null} */
let productNames = null;

async function loadDimensionMaps() {
  const r = await pgPool.query(
    "SELECT id, name FROM app.regions ORDER BY id ASC",
  );
  const p = await pgPool.query(
    "SELECT id, name FROM app.products ORDER BY id ASC",
  );
  regionNames = new Map(r.rows.map((row) => [Number(row.id), String(row.name)]));
  productNames = new Map(p.rows.map((row) => [Number(row.id), String(row.name)]));
}

function chEscape(str) {
  return str.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

/**
 * @param {string} sql
 * @returns {Promise<Record<string, unknown>[]>}
 */
async function clickhouseJsonRows(sql) {
  const base = clickhouseUrl.replace(/\/$/, "");
  const res = await fetch(`${base}/?default_format=JSONEachRow`, {
    method: "POST",
    headers: { "Content-Type": "text/plain; charset=utf-8" },
    body: sql,
  });
  if (!res.ok) {
    const t = await res.text();
    throw new Error(`ClickHouse HTTP ${res.status}: ${t}`);
  }
  const text = await res.text();
  if (!text.trim()) {
    return [];
  }
  return text
    .trim()
    .split("\n")
    .map((line) => JSON.parse(line));
}

/**
 * @param {URLSearchParams} params
 */
function buildFilters(params) {
  const conditions = [];
  const dateFrom = params.get("date_from");
  const dateTo = params.get("date_to");
  if (dateFrom) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateFrom)) {
      throw new Error("Invalid date_from (expected YYYY-MM-DD)");
    }
    conditions.push(`ts >= toDateTime('${chEscape(dateFrom)} 00:00:00')`);
  }
  if (dateTo) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateTo)) {
      throw new Error("Invalid date_to (expected YYYY-MM-DD)");
    }
    conditions.push(`ts < toDateTime('${chEscape(dateTo)} 00:00:00') + toIntervalDay(1)`);
  }
  const regionId = params.get("region_id");
  if (regionId !== null && regionId !== "") {
    const n = Number(regionId);
    if (!Number.isInteger(n) || n < 0) {
      throw new Error("Invalid region_id");
    }
    conditions.push(`region_id = ${n}`);
  }
  const productId = params.get("product_id");
  if (productId !== null && productId !== "") {
    const n = Number(productId);
    if (!Number.isInteger(n) || n < 0) {
      throw new Error("Invalid product_id");
    }
    conditions.push(`product_id = ${n}`);
  }
  const where =
    conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : "";
  return where;
}

/**
 * @param {string} groupByRaw
 * @returns {{ select: string, groupBy: string, aliases: string[] }}
 */
function parseGroupBy(groupByRaw) {
  if (!groupByRaw || !groupByRaw.trim()) {
    return { select: "", groupBy: "", aliases: [] };
  }
  const parts = groupByRaw
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
  const select = [];
  const group = [];
  const aliases = [];
  for (const p of parts) {
    if (p === "region" || p === "region_id") {
      select.push("region_id AS region_id");
      group.push("region_id");
      aliases.push("region_id");
    } else if (p === "product" || p === "product_id") {
      select.push("product_id AS product_id");
      group.push("product_id");
      aliases.push("product_id");
    } else if (p === "day" || p === "date") {
      select.push("toDate(ts) AS day");
      group.push("day");
      aliases.push("day");
    } else {
      throw new Error(`Unknown group_by dimension: ${p}`);
    }
  }
  if (select.length === 0) {
    return { select: "", groupBy: "", aliases: [] };
  }
  return {
    select: select.join(", "),
    groupBy: group.join(", "),
    aliases,
  };
}

/**
 * @param {import("http").IncomingMessage} req
 * @param {import("http").ServerResponse} res
 */
async function handleMetrics(req, res) {
  const url = new URL(req.url ?? "/", `http://127.0.0.1:${PORT}`);
  if (url.pathname !== "/api/metrics") {
    res.writeHead(404, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Not found" }));
    return;
  }
  if (req.method !== "GET") {
    res.writeHead(405, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Method not allowed" }));
    return;
  }

  try {
    const where = buildFilters(url.searchParams);
    const aggSql = `SELECT sum(value) AS total_value, count() AS event_count FROM analytics.events ${where}`;
    const aggRows = await clickhouseJsonRows(aggSql);
    const agg = aggRows[0] ?? {};
    const totalValue = Number(agg.total_value ?? 0);
    const eventCount = Number(agg.event_count ?? 0);

    const groupSpec = parseGroupBy(url.searchParams.get("group_by") ?? "");
    /** @type {Record<string, unknown>[]} */
    let groups = [];
    if (groupSpec.groupBy) {
      const groupSql = `SELECT ${groupSpec.select}, sum(value) AS total_value, count() AS event_count FROM analytics.events ${where} GROUP BY ${groupSpec.groupBy} ORDER BY ${groupSpec.groupBy}`;
      const rawGroups = await clickhouseJsonRows(groupSql);
      const withNames = url.searchParams.get("include_names") === "1";
      if (withNames) {
        if (!regionNames || !productNames) {
          await loadDimensionMaps();
        }
        groups = rawGroups.map((row) => {
          const out = { ...row };
          const rid = row.region_id;
          if (rid !== undefined && regionNames) {
            out.region_name = regionNames.get(Number(rid)) ?? null;
          }
          const pid = row.product_id;
          if (pid !== undefined && productNames) {
            out.product_name = productNames.get(Number(pid)) ?? null;
          }
          return out;
        });
      } else {
        groups = rawGroups;
      }
    }

    const body = {
      total_value: totalValue,
      event_count: eventCount,
      ...(groups.length > 0 ? { groups } : {}),
    };
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify(body));
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    res.writeHead(400, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: message }));
  }
}

const server = http.createServer((req, res) => {
  handleMetrics(req, res).catch((err) => {
    console.error(err);
    res.writeHead(500, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ error: "Internal server error" }));
  });
});

server.listen(PORT, "0.0.0.0", () => {
  console.log(`metrics API listening on ${PORT}`);
});

